 "assistant.action.offerClick": "«{label}» батырмасын баса аламын.",
 "assistant.click.missing": "«{label}» батырмасы экранда жоқ — қажеттісін өзіңіз басыңыз.",
 "tour.practice.card.title": "Жаттықтырғыш карточкасы",
 "tour.practice.card.text": "Карточканы бас — жаттықтырғыш ашылады. Төмендегі белгі өткенің үшін қанша токен берілетінін көрсетеді.",
 "tour.practice.catalog.title": "Каталогтар",
 "tour.practice.catalog.text": "Мұқабалары бар карточка тізімді толық ашады: видео, кітап, ән немесе ертегі таңда.",
 "tour.practice.tokens.title": "Барлық есептеулер",
 "tour.practice.tokens.text": "Аш — жаттығуда және сабақта не үшін қанша токен берілетінін көресің.",
 "tour.practice.grammar.title": "Грамматика және ойындар",
 "tour.practice.grammar.text": "Деңгей бойынша 125 тақырып, жылдам оқу және барлық мини-ойындар осы бөлімде.",
 "tour.help": "Бөлім қалай жұмыс істейді",
 "tour.home.goal.title": "Сенің мақсатың",
 "tour.home.goal.text": "Қай деңгейге жеткің келеді? Таңда — жол соған дейінгі бүкіл бағытты көрсетеді.",
 "tour.home.skills.title": "Күшті және әлсіз жақтар",
 "tour.home.skills.text": "Пайыздар практикадағы тапсырмалар бойынша есептеледі: қанша жауап бірінші әрекеттен дұрыс. Тапсырма көп болған сайын, сурет дәлірек.",
 "tour.home.recommend.title": "Бүгін не істеу керек",
 "tour.home.recommend.text": "Сенің деректерің бойынша бір кеңес: мерзімі жеткен үй жұмысы, әлсіз дағды немесе ұзақ уақыт практика болмаған.",
 "tour.home.schedule.title": "Кесте",
 "tour.home.schedule.text": "Алдағы аптаның сабақтары. Ашу үшін сабақты бас.",
 "tour.intro.title": "Бұл бөлім —",
 "tour.intro.cta": "Көрсету",
 "tour.intro.skip": "Өткізу",
 "tour.practice.intro.text": "Барлық дағдыға арналған жаттықтырғыштар мен мини-ойындар — өз қарқыныңмен өзің айналыс. Бір минутта не қайда екенін көрсетеміз.",
 "tour.learn.intro.text": "Сабақта өткеніңді қайтала: A0-ден C1-ге дейінгі деңгейлер картасы, ішінде — сабақтар ретімен. Қалай жүру керегін көрсетеміз.",
 "tour.lessons.intro.text": "Мұғаліммен сабақтар: ең жақын сабақ және барлық кездесулер күнтізбесі. Не қайда екенін көрсетеміз.",
 "tour.hw.intro.text": "Мұғалімнің тапсырмалары: жұмысты ашасың, жауабыңды тіркейсің де, тексеруге жібересің. Қалай істеу керегін көрсетеміз.",
 "tour.vocab.intro.text": "Деңгейлер мен тақырыптар бойынша сөздер және өз сөздігің — тапсырмаларда сақтаған сөздер сонда түседі. Бір минутта көрсетеміз.",
 "tour.plan.intro.text": "Мақсатыңызға дейінгі күнделікті жоспар: бүгін және осы аптада не істеу керек. Қалай пайдалану керегін көрсетеміз.",
 "tour.practice.skills.title": "Бес бөлім",
 "tour.practice.skills.text": "Тыңдалым, оқылым, жазылым, айтылым және грамматика. Әр бөлімнің өз түсі бар — басқанда, оның жаттықтырғыштары төменде жиналады.",
 "tour.practice.levels.title": "Материал деңгейі",
 "tour.practice.levels.text": "Кітаптарды, әндерді, жағдаяттарды және грамматика юниттерін таңдалған деңгейге сай іріктейді. «Барлығы» — бәрін көрсету.",
 "tour.learn.map.title": "Деңгейлер картасы",
 "tour.learn.map.text": "Арал — A0-ден C1-ге дейінгі бүкіл жол. Ондағы әр қала — деңгей, карта төменнен жоғары қарай айналады.",
 "tour.learn.current.title": "Сенің деңгейің",
 "tour.learn.current.text": "Карта осы жерден ашылады. Қала ішінде — сабақтар соқпағы: ретімен өтесің, юнит соңында тест күтеді.",
 "tour.learn.locked.title": "Жабық қалалар",
 "tour.learn.locked.text": "Жоғарғы деңгейлер ағымдағысын аяқтағанда ашылады.",
 "tour.lessons.tabs.title": "Екі қойынды",
 "tour.lessons.tabs.text": "«Онлайн» — мұғаліммен кесте бойынша сабақ. «Өз бетінше» — өз деңгейіңдегі курс материалдары, оларды өзің өтесің.",
 "tour.lessons.next.title": "Жақындағы сабақ",
 "tour.lessons.next.text": "Жоғарыдағы карточка — келесі сабақ. Мұғалім сабақты бастағанда, оған осы жерден кіресің.",
 "tour.lessons.calendar.title": "Күнтізбе",
 "tour.lessons.calendar.text": "Мұнда айдың барлық сабағы көрінеді — өткені де, жоспарланғаны да.",
 "tour.hw.list.title": "Жұмыстар тізімі",
 "tour.hw.list.text": "Жоғарыда — сені күтіп тұрғаны: берілген және пысықтауға қайтарылған. Төменде — тапсырылғаны мен тексерілгені.",
 "tour.hw.upload.title": "Сенің жауабың",
 "tour.hw.upload.text": "Жұмысың бар файлды тірке — сурет, құжат немесе аудио. Рұқсат етілген форматтар түйменің астында жазулы.",
 "tour.hw.submit.title": "Тексеруге жіберу",
 "tour.hw.submit.text": "Жұмыс мұғалімге кетеді; баға мен пікір осы карточкаға қайта оралады.",
 "tour.hw.back.title": "Барлық тапсырмалар",
 "tour.hw.back.text": "Осы жерден тізімге орал: қалған үй жұмыстары сонда, тапсырылғаны мен тексерілгені де.",
 "tour.vocab.levels.title": "Негізгі лексика",
 "tour.vocab.levels.text": "Ағылшын деңгейі бойынша негізгі сөздер. Өз деңгейің және одан төмені ашық.",
 "tour.vocab.fields.title": "Мамандық лексикасы",
