 "ieltsOb.p.diag.intro.honest": "Сөздікке де, көмекке де қарамай жауап беріңіз — сонда баға шындыққа жақын шығады. Жауаптар сақталады: қойындыны жауып, кейін жалғастыра аласыз.",
