 "ieltsSpeaking.p.sha.listText": "Сөйлемді тыңдап, дикторды қайталаңыз: белгі оның сөйлеу қарқынымен жылжиды. 0.75×-ке дейін баяулатуға және салыстыру үшін өзіңізді жазып алуға болады.",
