 "ieltsSpeaking.p.sha.modeHint.after": "«Жазып алу» батырмасын басып, сөйлемді қайталаңыз да, «Тоқтату» батырмасын басыңыз.",
 "ieltsSpeaking.p.sha.modeHint.with": "Сөйлем басынан ойнайды — дикторпен бір уақытта сөйлеңіз. Құлаққаппен жақсырақ, әйтпесе микрофон дикторды да жазып алады.",
