 "ieltsSpeaking.introTitle.part3": "Part 3 · талқылау",
 "ieltsSpeaking.intro.part1": "Емтихан алушы {n} сұрақ қояды. Бірден, 2–3 сөйлеммен жауап беріңіз — жазба сұрақтан кейін басталады.",
 "ieltsSpeaking.intro.part2": "Жазбалармен дайындалуға бір минут, содан кейін екі минутқа дейін монолог және емтихан алушының қысқа сұрағы.",
