 "ieltsSpeaking.lastTake": "соңғы жауап",
 "ieltsSpeaking.listText.part1": "Сіз туралы тақырыптар: үй, оқу, жұмыс, әдеттер — 20–30 секундтық қысқа жауаптар.",
 "ieltsSpeaking.listText.part2": "Сегіз түрлі карточка: адам, орын, оқиға, зат… Бір минут дайындық және екі минут сөйлеу.",
