 "ieltsGuideV.part.speaking.p1.text": "Өзің туралы қысқа сұрақтар: оқу, жұмыс, хобби.",
 "ieltsGuideV.part.speaking.p2.name": "Part 2",
 "ieltsGuideV.part.speaking.p2.text": "Карточка: бір минут дайындық және 2 минутқа дейін сөйлеу.",
 "ieltsGuideV.part.speaking.p3.name": "Part 3",
 "ieltsGuideV.part.speaking.p3.text": "Карточка тақырыбын талқылау: пікір мен себеп.",
 "ieltsGuideV.critTitle": "Қандай критерийлер бойынша бағалайды?",
 "ieltsGuideV.crit.listening": "Бір дұрыс жауап — бір балл, 40-тан|Дұрыс жауаптар саны кесте бойынша band-қа айналады|Қате жазылған жауап есептелмейді|Сөз шегі: артық сөз жауапты қате етеді",
 "ieltsGuideV.crit.reading": "Бір дұрыс жауап — бір балл, 40-тан|Academic пен General Training кестелері бөлек|Жауап мәтін бойынша және сөз шегінде|NOT GIVEN мен FALSE — әртүрлі жауап",
 "ieltsGuideV.crit.writing": "Task Achievement / Response — тапсырманың қаншалықты толық ашылғаны|Coherence and Cohesion — құрылым, абзац және байланыстырғыштар|Lexical Resource — лексиканың дәлдігі мен алуандығы|Grammatical Range and Accuracy — грамматиканың алуандығы мен дәлдігі",
 "ieltsGuideV.crit.speaking": "Fluency and Coherence — қарқын, кідіріс және логика|Lexical Resource — сөздер және басқаша айту|Grammatical Range and Accuracy — қатесіз әртүрлі құрылымдар|Pronunciation — түсініктілік, екпін және интонация",
 "ieltsGuideV.timeTitle": "Уақытты қалай бөлу керек?",
 "ieltsGuideV.time.listening": "Әр бөліктің алдында кідіріс бар — сұрақтарды алдын ала оқы.",
